export function buildBoundaryArcs(
  coords: [number, number][],
  color: [number, number, number] = [46 / 255, 110 / 255, 185 / 255]
) {
  const arcs: Array<{
    from: [number, number];
    to: [number, number];
    color: [number, number, number];
  }> = [];
  for (let i = 0; i < coords.length - 1; i++) {
    arcs.push({
      from: coords[i],
      to: coords[i + 1],
      color,
    });
  }
  // Close loop
  if (coords.length > 2) {
    arcs.push({
      from: coords[coords.length - 1],
      to: coords[0],
      color,
    });
  }
  return arcs;
}

export function getStateBoundaryKey(stateName?: string): string | null {
  if (!stateName) return null;
  const normalized = stateName.toLowerCase().replace(/[^a-z]/g, "");
  if (normalized.includes("rajasthan")) return "rajasthan";
  if (normalized.includes("uttarpradesh") || normalized.includes("up")) return "uttarPradesh";
  if (normalized.includes("gujarat")) return "gujarat";
  if (normalized.includes("maharashtra")) return "maharashtra";
  if (normalized.includes("karnataka")) return "karnataka";
  return null;
}

